import { afterEach, beforeEach, describe, expect, expectTypeOf, it, type Mock, vi } from "vitest";

vi.mock("../runtime-input.js", () => ({
	resolveRuntimeInput: vi.fn(),
}));

import { ExecutionError } from "../error.js";
import {
	type CapabilityContext,
	TerminalError,
	Worker,
	type WorkflowConfiguration,
} from "../index.js";
import { resolveRuntimeInput } from "../runtime-input.js";
import {
	type NotionPageCreatedEvent,
	type NotionPageCreatedTrigger,
	triggers,
	WORKFLOW_TRIGGER_TYPES,
	type WorkflowTriggerType,
} from "../triggers.generated.js";
import { createWorkflowCapability } from "./workflow.js";

const pageCreatedEvent: NotionPageCreatedEvent = {
	type: "notion.page.created",
	vendor: "notion",
	message: "Page created",
	actor: {
		id: "user-1",
		displayName: "Ada Lovelace",
		email: "ada@example.com",
		vendorActor: {
			vendor: "notion",
			id: "user-1",
			displayName: "Ada Lovelace",
			handle: null,
			type: "user",
			url: null,
		},
	},
	url: "https://www.notion.so/page-1",
	timestamp: "2026-06-26T12:00:00.000Z",
	page: {
		id: "page-1",
		Name: "Welcome",
		Status: "New",
	},
	content: "# Welcome\n\nHello, world!",
	edits: [
		{
			before: null,
			after: {
				id: "page-1",
				Name: "Welcome",
				Status: "New",
			},
			afterContent: "# Welcome\n\nHello, world!",
			contentChanged: true,
			timestamp: 1_782_477_600_000,
			editedBy: null,
		},
	],
};

describe("createWorkflowCapability", () => {
	let stdoutSpy: Mock<typeof process.stdout.write>;
	const resolveRuntimeInputMock = vi.mocked(resolveRuntimeInput);

	beforeEach(() => {
		stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		resolveRuntimeInputMock.mockImplementation(async (fallback) => fallback);
	});

	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("declares a page-created trigger without a database", () => {
		expect(triggers.notionPageCreated()).toEqual({
			type: "notion.page.created",
		});
	});

	it("omits unsupported workflow triggers", () => {
		type UnsupportedTriggerType = Extract<
			WorkflowTriggerType,
			"notion.agent.mentioned" | "webhooks.webhook"
		>;

		expectTypeOf<UnsupportedTriggerType>().toEqualTypeOf<never>();
		expect(WORKFLOW_TRIGGER_TYPES).not.toContain("notion.agent.mentioned");
		expect(WORKFLOW_TRIGGER_TYPES).not.toContain("webhooks.webhook");
		expect(triggers).not.toHaveProperty("notionAgentMentioned");
		expect(triggers).not.toHaveProperty("webhook");
	});

	it("exposes the recurrence trigger as scheduled", () => {
		expect(triggers.scheduled()).toEqual({ type: "recurrence" });
		expect(triggers).not.toHaveProperty("recurrence");
	});

	it("requires trigger declarations in workflow configuration", () => {
		type PageAddedConfiguration = WorkflowConfiguration<readonly [NotionPageCreatedTrigger]>;
		type ConfigurationWithoutTriggers = Omit<PageAddedConfiguration, "triggers">;

		expectTypeOf<ConfigurationWithoutTriggers>().not.toMatchTypeOf<PageAddedConfiguration>();
	});

	it("infers the canonical page-created event and capability context", () => {
		createWorkflowCapability("pageAdded", {
			title: "Page Added",
			description: "Runs when a page is added",
			triggers: [triggers.notionPageCreated()],
			execute: (event, context) => {
				expectTypeOf(event).toEqualTypeOf<NotionPageCreatedEvent>();
				expectTypeOf(event.type).toEqualTypeOf<"notion.page.created">();
				expectTypeOf(context).toEqualTypeOf<CapabilityContext>();
			},
		});
	});

	it("includes triggers in capability config and the worker manifest", () => {
		const worker = new Worker();
		worker.workflow("pageAdded", {
			title: "Page Added",
			description: "Runs when a page is added",
			triggers: [triggers.notionPageCreated()],
			execute: () => {},
		});

		expect(worker.manifest.capabilities).toEqual([
			{
				_tag: "workflow",
				key: "pageAdded",
				config: {
					title: "Page Added",
					description: "Runs when a page is added",
					triggers: [{ type: "notion.page.created" }],
				},
			},
		]);
	});

	it("executes with the public event and capability context", async () => {
		const execute = vi.fn();
		const capability = createWorkflowCapability("pageAdded", {
			title: "Page Added",
			description: "Runs when a page is added",
			triggers: [triggers.notionPageCreated()],
			execute,
		});

		await expect(capability.handler(pageCreatedEvent, { concreteOutput: true })).resolves.toEqual({
			status: "success",
		});
		expect(execute).toHaveBeenCalledWith(
			pageCreatedEvent,
			expect.objectContaining({ notion: expect.any(Object) }),
		);
		expect(stdoutSpy).not.toHaveBeenCalled();
	});

	it("uses a file-backed event instead of the inline event", async () => {
		const execute = vi.fn();
		const capability = createWorkflowCapability("pageAdded", {
			title: "Page Added",
			description: "Runs when a page is added",
			triggers: [triggers.notionPageCreated()],
			execute,
		});
		const fileEvent = { ...pageCreatedEvent, message: "File event" };
		resolveRuntimeInputMock.mockResolvedValue(fileEvent);

		await capability.handler(pageCreatedEvent, { concreteOutput: true });

		expect(execute).toHaveBeenCalledWith(fileEvent, expect.anything());
	});

	it("writes the success envelope by default", async () => {
		const capability = createWorkflowCapability("pageAdded", {
			title: "Page Added",
			description: "Runs when a page is added",
			triggers: [triggers.notionPageCreated()],
			execute: () => {},
		});

		await capability.handler(pageCreatedEvent);

		expect(stdoutSpy).toHaveBeenCalledWith(
			'\n<__notion_output__>{"_tag":"success","value":{"status":"success"}}</__notion_output__>\n',
		);
	});

	it("writes and throws an execution error", async () => {
		const capability = createWorkflowCapability("pageAdded", {
			title: "Page Added",
			description: "Runs when a page is added",
			triggers: [triggers.notionPageCreated()],
			execute: () => {
				throw new Error("Something went wrong");
			},
		});

		await expect(capability.handler(pageCreatedEvent)).rejects.toThrow(ExecutionError);
		expect(stdoutSpy).toHaveBeenCalledWith(
			expect.stringContaining(
				'"_tag":"error","error":{"name":"ExecutionError","message":"Error during worker execution: Error: Something went wrong"',
			),
		);
		expect(
			stdoutSpy.mock.calls.filter(([output]) => String(output).includes("<__notion_error__>")),
		).toHaveLength(1);
	});

	it("writes and rethrows a terminal error", async () => {
		class InvalidPageError extends TerminalError {}

		const capability = createWorkflowCapability("pageAdded", {
			title: "Page Added",
			description: "Runs when a page is added",
			triggers: [triggers.notionPageCreated()],
			execute: () => {
				throw new InvalidPageError("The page cannot be processed", {
					cause: new Error("The page is archived"),
				});
			},
		});

		const result = capability.handler(pageCreatedEvent);
		await expect(result).rejects.toBeInstanceOf(InvalidPageError);
		await expect(result).rejects.toMatchObject({
			cause: expect.objectContaining({ message: "The page is archived" }),
		});
		expect(stdoutSpy).toHaveBeenCalledWith(
			expect.stringContaining(
				'"_tag":"error","error":{"_tag":"terminal","name":"TerminalError","message":"The page cannot be processed"',
			),
		);
		const notionErrors = stdoutSpy.mock.calls
			.map(([output]) => String(output))
			.filter((output) => output.includes("<__notion_error__>"));
		expect(notionErrors).toHaveLength(1);
		expect(notionErrors[0]).toContain(
			'<__notion_error__>{"name":"TerminalError","message":"The page cannot be processed","stacktrace":',
		);
		expect(notionErrors[0]).toContain(
			'"cause":{"name":"Error","message":"The page is archived","stacktrace":',
		);
	});
});
